import os
from reportlab.lib.units import inch
from reportlab.platypus import Paragraph, Spacer, PageBreak, KeepTogether
from compendium_base import (
    get_custom_stylesheet, create_banner_header, create_callout,
    create_example, create_figure, create_custom_table, render_pdf
)

def build_lecture_3():
    styles = get_custom_stylesheet()
    story = []

    # 1. Header Banner
    topics = [
        "3.1 Semiconductor Diode Physics, Shockley Equation & Reverse Saturation Current",
        "3.2 Dynamic Junction Resistance Derivation & Small-Signal AC Models",
        "3.3 Diode Approximations: Ideal, Practical (Offset) & Piecewise Linear Models",
        "3.4 Half-Wave & Full-Wave Rectification: Rigorous Mathematical Fourier Analysis",
        "3.5 Filter Capacitors, Ripple Factor Derivation & Transformer Utilization Factor (TUF)",
        "3.6 Peak Inverse Voltage (PIV) & Diode Selection Criteria for Harsh Field Environments",
        "3.7 Diode Waveform Conditioning: Biased Shunt/Series Clippers & Voltage Clampers",
        "3.8 Voltage Multipliers (Doublers, Triplers) & Surge Inrush Current Limiting",
        "3.9 Agricultural Power Supply Design: 24V Solenoid & 12V Microcontroller Rails",
        "3.10 Practical Laboratory Bench Protocol: Rectifier Ripple & Clipping Verification",
        "3.11 Tanzanian Agricultural Field Case Studies: Mbarali Rice & Kilombero Cane Systems",
        "3.12 Comprehensive Self-Assessment: Conceptual, Quantitative & System Design Problems"
    ]
    story.extend(create_banner_header(3, "Semiconductor Diode & Rectifier Circuits", topics))

    # -------------------------------------------------------------
    # SECTION 1: EXECUTIVE OVERVIEW & FOUNDATIONAL PHYSICS
    # -------------------------------------------------------------
    story.append(Paragraph("3.1 Semiconductor Diode Physics & Mathematical Models", styles['SecH1']))
    story.append(Paragraph(
        "The semiconductor diode is the foundational non-linear two-terminal electronic device formed by the metallurgical junction "
        "of P-type and N-type semiconductors. In agricultural engineering systems, the diode is indispensable: it acts as a one-way electrical "
        "valve enabling AC-to-DC electrical power conversion, protects sensitive sensor instrumentation against reverse polarity during tractor battery "
        "swaps, suppresses inductive flyback spikes generated by irrigation solenoid valves, and clamps analog telemetry signals within safe "
        "microcontroller input thresholds (0V to 3.3V).",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "Under thermal equilibrium and externally applied bias voltage <i>V_D</i>, carrier transport across the PN junction consists of competing "
        "drift and diffusion mechanisms. The total net current <i>I_D</i> flowing from anode to cathode is governed with exceptional precision by the "
        "celebrated <b>Shockley Diode Equation</b>:",
        styles['DocBody']
    ))
    story.append(Paragraph("<b>I<sub>D</sub> = I<sub>S</sub> · [ exp( V<sub>D</sub> / (η · V<sub>T</sub>) ) - 1 ] &nbsp;&nbsp;[Amperes]</b>", styles['FormulaBox']))
    story.append(Paragraph(
        "where the governing physical parameters are defined as follows:<br/>"
        "• <b>I<sub>S</sub></b> is the reverse saturation current (leakage current) arising from thermal generation of minority carriers across the depletion layer, typically 10⁻¹² A to 10⁻⁹ A for silicon, and 10⁻⁶ A for germanium at room temperature (300 K).<br/>"
        "• <b>V<sub>D</sub></b> is the terminal voltage applied across the diode junction (positive for forward bias, negative for reverse bias).<br/>"
        "• <b>η (eta)</b> is the ideality factor (emission coefficient), reflecting carrier recombination within the depletion region. For silicon diodes, η ≈ 2 at low currents (where recombination dominates) and approaches η ≈ 1 at higher injection levels; for germanium, η ≈ 1 across most operating ranges.<br/>"
        "• <b>V<sub>T</sub></b> is the thermal voltage, given by <b>V<sub>T</sub> = (k · T) / q</b>, where <i>k = 1.3806 × 10⁻²³ J/K</i> is Boltzmann's constant, <i>q = 1.6022 × 10⁻¹⁹ C</i> is elementary charge, and <i>T</i> is absolute junction temperature in Kelvin. At standard room temperature (T = 300 K / 26.85°C), <b>V<sub>T</sub> ≈ 25.86 mV ≈ 26 mV</b>.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "<b>Temperature Dependence of Reverse Saturation Current:</b><br/>"
        "The reverse saturation current <i>I_S</i> is strongly temperature-dependent because the intrinsic carrier concentration <i>n_i</i> varies exponentially with temperature (<i>n_i² ∝ T³ · exp(-E_g / (k·T))</i>). "
        "For silicon PN junctions, <i>I_S</i> approximately doubles for every 10°C increase in junction temperature:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>I<sub>S</sub>(T<sub>2</sub>) = I<sub>S</sub>(T<sub>1</sub>) · 2<sup>(T<sub>2</sub> - T<sub>1</sub>) / 10</sup></b><br/>"
        "In tropical agricultural machinery operating under direct sun in Morogoro or Shinyanga where ambient temperatures reach 40°C and tractor engine compartments exceed 85°C, "
        "a reverse leakage current of 10 nA at 25°C escalates to over 640 nA at 85°C. This leakage must be accounted for in high-impedance soil moisture and pH sensor conditioning amplifiers.",
        styles['DocBody']
    ))

    story.append(create_figure("fig3_1_diode_iv_characteristics.png", "Complete Diode I-V Characteristic Curve Illustrating Forward Conduction, Reverse Leakage, Knee Voltage, and Zener/Avalanche Breakdown", target_width=5.5*inch))

    # -------------------------------------------------------------
    # SECTION 2: DERIVATION OF JUNCTION RESISTANCE
    # -------------------------------------------------------------
    story.append(Paragraph("3.2 Static vs Dynamic Junction Resistance Derivations", styles['SecH1']))
    story.append(Paragraph(
        "Because the PN junction diode exhibits a non-linear exponential current-voltage relationship, Ohm's law (<i>R = V/I</i>) cannot be applied globally. "
        "Engineers must distinguish rigorously between <b>Static (DC) Resistance</b> and <b>Dynamic (AC or Small-Signal) Resistance</b>.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "<b>1. Static (DC) Resistance (R<sub>D</sub>):</b><br/>"
        "The static resistance at any specific DC operating point (Q-point: <i>V_DQ, I_DQ</i>) is defined as the ratio of absolute DC voltage to absolute DC current:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>R<sub>D</sub> = V<sub>DQ</sub> / I<sub>DQ</sub></b><br/>"
        "Below the knee voltage (e.g., <i>V_D < 0.5 V</i> for silicon), <i>I_D</i> is negligible, yielding an extremely high static resistance (megaohms). "
        "Once fully forward biased (<i>V_D = 0.75 V, I_D = 20 mA</i>), static resistance collapses to <i>R_D = 0.75 V / 0.02 A = 37.5 Ω</i>.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "<b>2. Mathematical Derivation of Dynamic (AC) Resistance (r<sub>d</sub>):</b><br/>"
        "When a small AC signal is superimposed upon the DC bias point, the diode presents an incremental or small-signal resistance defined as the reciprocal of the slope of the I-V curve at the Q-point:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>r<sub>d</sub> = ( dV<sub>D</sub> / dI<sub>D</sub> ) |<sub>Q-point</sub> = 1 / ( dI<sub>D</sub> / dV<sub>D</sub> )</b>",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "Starting from the Shockley equation, under forward bias where <i>exp(V_D / (η·V_T)) >> 1</i>, we can write:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>I<sub>D</sub> ≈ I<sub>S</sub> · exp( V<sub>D</sub> / (η · V<sub>T</sub>) )</b><br/>"
        "Differentiating <i>I_D</i> with respect to <i>V_D</i>:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>dI<sub>D</sub> / dV<sub>D</sub> = I<sub>S</sub> · [ 1 / (η · V<sub>T</sub>) ] · exp( V<sub>D</sub> / (η · V<sub>T</sub>) ) = I<sub>D</sub> / (η · V<sub>T</sub>)</b><br/>"
        "Inverting this dynamic conductance yields the fundamental dynamic junction resistance equation:",
        styles['DocBody']
    ))
    story.append(Paragraph("<b>r<sub>d</sub> = (η · V<sub>T</sub>) / I<sub>D</sub> &nbsp;&nbsp;≈&nbsp;&nbsp; 26 mV / I<sub>D</sub> &nbsp;&nbsp;(for η = 1 at 300 K) &nbsp;&nbsp;[Ohms]</b>", styles['FormulaBox']))
    story.append(Paragraph(
        "<b>Total Dynamic Resistance:</b> Accounting for the physical ohmic bulk resistance of the P and N semiconductor material and the metallic contact leads (<i>r_B</i>), "
        "the total small-signal resistance is <b>r'<sub>d</sub> = r<sub>d</sub> + r<sub>B</sub></b>, where <i>r_B</i> typically ranges from 0.1 Ω for high-power rectifier diodes to 2 Ω for small-signal switching diodes.",
        styles['DocBody']
    ))

    # -------------------------------------------------------------
    # SECTION 3: DIODE APPROXIMATIONS & EQUIVALENT CIRCUITS
    # -------------------------------------------------------------
    story.append(Paragraph("3.3 Diode Approximations & Practical Engineering Models", styles['SecH1']))
    story.append(Paragraph(
        "In circuit analysis and computer-aided design (SPICE), analyzing non-linear exponential transcendental equations by hand is intractable. "
        "Engineers employ three standardized hierarchical approximations depending on the required calculation precision:",
        styles['DocBody']
    ))

    approx_headers = ["Approximation Model", "Equivalent Circuit Components", "Forward Condition", "Reverse Condition", "Typical Agricultural Application"]
    approx_rows = [
        ["1st Approx: Ideal Diode", "Perfect switch (zero resistance when closed, infinite when open)", "Closed switch: V_D = 0 V, I_D > 0", "Open switch: I_D = 0 A, V_D < 0", "Initial mental checks, high-voltage AC power distribution (>230V)."],
        ["2nd Approx: Practical / Offset", "Ideal switch in series with DC barrier battery (V_K = 0.7V Si, 0.3V Ge)", "V_D = 0.7 V for any forward current I_D > 0", "Open switch: I_D = 0 A for V_D < 0.7 V", "DC power supplies, relay flyback protection, battery charger design."],
        ["3rd Approx: Piecewise Linear", "Ideal switch + DC battery (V_K) + bulk resistance (r_B)", "V_D = V_K + I_D · r_B for V_D ≥ V_K", "Open switch in parallel with reverse resistance r_R", "High-current motor drives, precise telemetry clippers, solar inverters."]
    ]
    story.append(create_custom_table(approx_headers, approx_rows, [1.4*inch, 1.8*inch, 1.4*inch, 1.4*inch, 1.4*inch]))
    story.append(Spacer(1, 8))

    # -------------------------------------------------------------
    # SECTION 4: RECTIFICATION CIRCUITS (HALF-WAVE & FULL-WAVE)
    # -------------------------------------------------------------
    story.append(Paragraph("3.4 Half-Wave & Full-Wave Rectification: Rigorous Mathematical Analysis", styles['SecH1']))
    story.append(Paragraph(
        "Rectification is the conversion of bidirectional alternating current (AC) into unidirectional direct current (DC). "
        "Agricultural sensors, microcontrollers (ESP32, STM32, Arduino), and solenoid drivers require steady DC voltages derived from 230V, 50 Hz TANESCO grid mains "
        "or tractor engine alternators. Here we provide the complete mathematical derivations of DC output voltages, RMS values, ripple factors, and conversion efficiencies.",
        styles['DocBody']
    ))

    story.append(create_figure("fig3_2_bridge_rectifier_schematic.png", "Full-Wave Bridge Rectifier Schematic with AC Mains Transformer, 4-Diode Bridge, Smoothing Capacitor, and DC Load", target_width=5.5*inch))

    story.append(Paragraph("<b>1. Half-Wave Rectifier Mathematical Derivations:</b>", styles['SecH2']))
    story.append(Paragraph(
        "Let the input sinusoidal AC voltage applied to a half-wave rectifier be <i>v_in(t) = V_m · sin(ωt)</i>, where <i>V_m</i> is peak secondary voltage and <i>ω = 2πf</i>.<br/>"
        "The diode conducts only during the positive half-cycle (<i>0 ≤ ωt ≤ π</i>), blocking during the negative half-cycle (<i>π ≤ ωt ≤ 2π</i>).<br/>"
        "• <b>Average (DC) Output Voltage (V<sub>dc</sub>):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>V<sub>dc</sub> = (1 / 2π) ∫₀<sup>π</sup> V<sub>m</sub> · sin(θ) dθ = (V<sub>m</sub> / 2π) · [ -cos(θ) ]₀<sup>π</sup> = (V<sub>m</sub> / 2π) · [ -(-1) - (-1) ] = V<sub>m</sub> / π ≈ 0.318 · V<sub>m</sub></b><br/>"
        "Accounting for the practical silicon diode barrier drop <i>V_K = 0.7 V</i>: <b>V<sub>dc</sub> = (V<sub>m</sub> - 0.7) / π</b>.<br/>"
        "• <b>RMS Output Voltage (V<sub>rms</sub>):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>V<sub>rms</sub> = √[ (1 / 2π) ∫₀<sup>π</sup> (V<sub>m</sub> · sin(θ))² dθ ] = V<sub>m</sub> / 2 = 0.500 · V<sub>m</sub></b><br/>"
        "• <b>Ripple Factor (γ):</b> Defined as the ratio of effective AC ripple component to the DC component:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>γ = V<sub>ac,rms</sub> / V<sub>dc</sub> = √[ (V<sub>rms</sub> / V<sub>dc</sub>)² - 1 ] = √[ ((V<sub>m</sub>/2) / (V<sub>m</sub>/π))² - 1 ] = √[ (π/2)² - 1 ] = √[ 2.4674 - 1 ] = √1.4674 ≈ 1.21 (121%)</b><br/>"
        "A ripple factor of 121% is exceptionally poor; the pulsating output contains more fluctuating AC power than useful DC power.<br/>"
        "• <b>Rectification Efficiency (η<sub>rect</sub>):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>η<sub>rect</sub> = P<sub>dc</sub> / P<sub>ac,in</sub> = (I<sub>dc</sub>² · R<sub>L</sub>) / (I<sub>rms</sub>² · (R<sub>L</sub> + r<sub>d</sub>)) ≈ (V<sub>m</sub>/π)² / (V<sub>m</sub>/2)² = 4 / π² ≈ 40.53%</b>.<br/>"
        "• <b>Peak Inverse Voltage (PIV):</b> During the negative half-cycle, the diode withstands the entire peak AC voltage: <b>PIV = V<sub>m</sub></b>.",
        styles['DocBody']
    ))

    story.append(Paragraph("<b>2. Full-Wave Bridge Rectifier Mathematical Derivations:</b>", styles['SecH2']))
    story.append(Paragraph(
        "The bridge rectifier uses four diodes arranged in a closed loop (Graetz bridge). During both half-cycles, two diodes conduct simultaneously in series with load <i>R_L</i>, "
        "directing current through <i>R_L</i> in the exact same direction.<br/>"
        "• <b>Average (DC) Output Voltage (V<sub>dc</sub>):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>V<sub>dc</sub> = (1 / π) ∫₀<sup>π</sup> V<sub>m</sub> · sin(θ) dθ = (2 · V<sub>m</sub>) / π ≈ 0.637 · V<sub>m</sub></b><br/>"
        "Accounting for two series silicon diode drops (<i>2 · V_K = 1.4 V</i>): <b>V<sub>dc</sub> = (2 · (V<sub>m</sub> - 1.4 V)) / π</b>.<br/>"
        "• <b>RMS Output Voltage (V<sub>rms</sub>):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>V<sub>rms</sub> = √[ (1 / π) ∫₀<sup>π</sup> (V<sub>m</sub> · sin(θ))² dθ ] = V<sub>m</sub> / √2 ≈ 0.707 · V<sub>m</sub></b><br/>"
        "• <b>Ripple Factor (γ):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>γ = √[ (V<sub>rms</sub> / V<sub>dc</sub>)² - 1 ] = √[ ((V<sub>m</sub>/√2) / (2V<sub>m</sub>/π))² - 1 ] = √[ (π² / 8) - 1 ] = √[ 1.2337 - 1 ] = √0.2337 ≈ 0.482 (48.2%)</b><br/>"
        "This is less than half the ripple of the half-wave rectifier, and the ripple frequency doubles to <i>2 · f = 100 Hz</i> (on 50 Hz TANESCO grid), making filtering vastly easier.<br/>"
        "• <b>Rectification Efficiency (η<sub>rect</sub>):</b><br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>η<sub>rect</sub> = (2V<sub>m</sub>/π)² / (V<sub>m</sub>/√2)² = 8 / π² ≈ 81.06%</b> (Double the half-wave efficiency!).<br/>"
        "• <b>Peak Inverse Voltage (PIV):</b> In a bridge rectifier, the reverse voltage across any non-conducting diode is clamped by the other conducting diodes to: <b>PIV = V<sub>m</sub> - V<sub>K</sub> ≈ V<sub>m</sub></b>. "
        "Contrast this with a center-tapped full-wave rectifier where <b>PIV = 2 · V<sub>m</sub></b>.",
        styles['DocBody']
    ))

    story.append(create_figure("fig3_3_rectifier_waveforms.png", "Fourier Waveform Analysis Comparing Half-Wave vs Full-Wave Unfiltered & Capacitor-Filtered DC Outputs", target_width=5.5*inch))

    # -------------------------------------------------------------
    # SECTION 5: FILTER CAPACITORS & RIPPLE DERIVATION
    # -------------------------------------------------------------
    story.append(Paragraph("3.5 Capacitor Smoothing Filters & Ripple Factor Equations", styles['SecH1']))
    story.append(Paragraph(
        "The raw pulsating output of a rectifier is unsuitable for precision digital controllers and analog instrumentation. "
        "Placing a large electrolytic reservoir capacitor <i>C</i> in parallel with load resistor <i>R_L</i> smooths the pulsations. "
        "The capacitor charges to peak voltage <i>V_p = V_m - 2V_K</i> in a brief conduction angle <i>Δt</i> when secondary voltage exceeds capacitor voltage, "
        "and discharges exponentially through <i>R_L</i> during the prolonged non-conducting interval.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "<b>Derivation of Peak-to-Peak Ripple Voltage (V<sub>r(p-p)</sub>):</b><br/>"
        "Assuming linear discharge approximation (valid when discharge time constant <i>R_L · C >> T</i>):<br/>"
        "The charge lost by the capacitor during discharge time <i>T_d ≈ T_ripple = 1 / f_r</i> is <i>ΔQ = I<sub>dc</sub> · T_ripple = I<sub>dc</sub> / f_r</i>.<br/>"
        "Since <i>ΔQ = C · V<sub>r(p-p)</sub></i>, we obtain the fundamental ripple equation:",
        styles['DocBody']
    ))
    story.append(Paragraph("<b>V<sub>r(p-p)</sub> = I<sub>dc</sub> / ( f<sub>r</sub> · C ) = V<sub>dc</sub> / ( f<sub>r</sub> · R<sub>L</sub> · C ) &nbsp;&nbsp;[Volts peak-to-peak]</b>", styles['FormulaBox']))
    story.append(Paragraph(
        "For a full-wave rectifier on 50 Hz TANESCO mains, ripple frequency is <i>f_r = 2 · 50 Hz = 100 Hz</i>. For half-wave, <i>f_r = 50 Hz</i>.<br/>"
        "The average DC output voltage is depressed by half the peak-to-peak ripple:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>V<sub>dc</sub> = V<sub>p</sub> - ( V<sub>r(p-p)</sub> / 2 ) = V<sub>p</sub> - [ I<sub>dc</sub> / ( 2 · f<sub>r</sub> · C ) ]</b><br/>"
        "The RMS value of an approximately triangular ripple waveform is <i>V<sub>r,rms</sub> = V<sub>r(p-p)</sub> / (2 · √3)</i>.<br/>"
        "Therefore, the RMS ripple factor of a capacitor-filtered full-wave rectifier is:",
        styles['DocBody']
    ))
    story.append(Paragraph("<b>γ = V<sub>r,rms</sub> / V<sub>dc</sub> = 1 / ( 4 · √3 · f · R<sub>L</sub> · C ) &nbsp;&nbsp;≈&nbsp;&nbsp; 1 / ( 346.4 · R<sub>L</sub> · C ) &nbsp;&nbsp;(at 50 Hz)</b>", styles['FormulaBox']))
    story.append(Paragraph(
        "<b>Diode Conduction Angle & Repetitive Peak Surge Current:</b><br/>"
        "Because the filter capacitor supplies the load current during most of the period, the rectifying diodes conduct only during a narrow time window <i>Δt</i>. "
        "To deliver the total charge <i>Q</i> required by the load, the repetitive peak forward diode current <i>I<sub>peak</sub></i> spikes to many times the average DC load current:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>I<sub>peak</sub> ≈ I<sub>dc</sub> · [ 1 + π · √( 2 · V<sub>p</sub> / V<sub>r(p-p)</sub> ) ]</b><br/>"
        "In a 2A agricultural DC actuator power supply with 5% ripple, peak diode current pulses exceed 25 A! "
        "Engineers must ensure the diode's repetitive surge rating (<i>I_FRM</i>) and non-repetitive surge rating (<i>I_FSM</i>) comfortably accommodate these spikes.",
        styles['DocBody']
    ))

    # -------------------------------------------------------------
    # SECTION 6: CLIPPERS & CLAMPERS
    # -------------------------------------------------------------
    story.append(Paragraph("3.6 Diode Clippers, Clampers & Voltage Multipliers", styles['SecH1']))
    story.append(Paragraph(
        "<b>1. Diode Clippers (Limiters):</b><br/>"
        "Clipper circuits modify input waveforms by clipping off portions above or below designated reference voltage levels without distorting the remaining waveform. "
        "In agricultural engineering, clippers are primarily used for <b>sensor overvoltage protection</b>. For instance, an analog ultrasonic fuel level sensor "
        "operating from a tractor's 12V battery can accidentally output 12V during faults; a diode clipper clamped to the 3.3V rail shunts excess current, preventing catastrophic destruction of the microcontroller ADC.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "• <b>Positive Biased Shunt Clipper:</b> Diode cathode connected to DC bias voltage <i>V_bias</i>, anode to signal line. When input <i>v_in > V_bias + 0.7 V</i>, diode conducts, clamping output to <i>V_out = V_bias + 0.7 V</i>.<br/>"
        "• <b>Negative Biased Shunt Clipper:</b> Diode anode connected to -<i>V_bias</i>, cathode to signal line. Clips signal below -(<i>V_bias + 0.7 V</i>).<br/>"
        "• <b>Symmetrical Double-Ended Clipper:</b> Two back-to-back anti-parallel diodes clamp analog sensor voltages safely between -0.7V and +3.3V.",
        styles['DocBody']
    ))

    story.append(create_figure("fig3_4_clipper_clamper_circuits.png", "Diode Waveform Conditioning Circuits: Biased Clipper Limiting Overvoltage & Clamper Restoring DC Level", target_width=5.5*inch))

    story.append(Paragraph(
        "<b>2. Diode Clampers (DC Restorers):</b><br/>"
        "A clamper circuit shifts an AC signal by adding a positive or negative DC level without changing the wave shape or peak-to-peak amplitude. "
        "Clampers require three components: a capacitor, a diode, and a resistor (with <i>R_L · C >> 10 · T</i>).<br/>"
        "• <b>Positive Clamper:</b> Clamps the negative peak of an AC signal to 0V (or -0.7V), shifting the entire waveform upward so that it becomes entirely positive. "
        "Crucial in optical grain counters and capacitive soil moisture probe conditioning where capacitive AC coupling removes the DC baseline.<br/>"
        "• <b>Negative Clamper:</b> Clamps the positive peak of an AC signal to 0V, shifting the entire waveform into the negative voltage region.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "<b>3. Voltage Multipliers:</b><br/>"
        "Cascading diodes and capacitors allows generating high DC voltages (2×, 3×, 4× peak AC voltage) without heavy step-up transformers. "
        "In agriculture, half-wave voltage doublers and triplers power electric predator deterrent fences (livestock perimeter security in pastoral regions) "
        "and electrostatic pesticide spray nozzles to induce electrostatic attraction between spray droplets and plant foliage.",
        styles['DocBody']
    ))

    # -------------------------------------------------------------
    # SECTION 6B: DC LOAD LINE & INRUSH SURGE ANALYSIS
    # -------------------------------------------------------------
    story.append(Paragraph("3.7 Diode DC Load Line Analysis & Inrush Surge Suppression", styles['SecH1']))
    story.append(Paragraph(
        "<b>1. Graphical DC Load Line Analysis:</b><br/>"
        "When an exact analytical solution for a diode circuit with a series resistor <i>R</i> and DC source <i>V_S</i> is difficult due to the "
        "exponential nature of the Shockley equation, the <b>DC Load Line</b> provides an intuitive and exact graphical solution. "
        "Applying Kirchhoff's Voltage Law (KVL) around the loop:<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>V_S - I_D · R - V_D = 0 &implies; I_D = (V_S / R) - (V_D / R)</b><br/>"
        "This is a straight-line equation on the <i>I_D</i> versus <i>V_D</i> plane with:<br/>"
        "• Vertical intercept (<i>V_D = 0</i>): <b>I_D(max) = V_S / R</b> (the short-circuit current).<br/>"
        "• Horizontal intercept (<i>I_D = 0</i>): <b>V_D(max) = V_S</b> (the open-circuit voltage).<br/>"
        "• Slope: <b>-1 / R</b>.<br/>"
        "The unique intersection of this straight load line with the non-linear exponential device curve defines the precise <b>Quiescent Operating Point (Q-point: V_DQ, I_DQ)</b>.",
        styles['DocBody']
    ))
    story.append(Paragraph(
        "<b>2. Capacitor Inrush Surge Current Dynamics & NTC Protection:</b><br/>"
        "At the exact instant an uncharged filter capacitor (<i>C</i>) is energized at peak secondary AC voltage (<i>V_m</i>), "
        "an uncharged capacitor presents an instantaneous short circuit (<i>V_C(0) = 0</i>). "
        "The resulting instantaneous inrush surge current is limited only by secondary transformer winding resistance <i>R_sec</i>, "
        "diode bulk resistance <i>r_B</i>, and capacitor Equivalent Series Resistance (ESR):<br/>"
        "&nbsp;&nbsp;&nbsp;&nbsp;<b>I_surge(peak) = (V_m - 2·V_K) / ( R_sec + 2·r_B + ESR )</b><br/>"
        "In heavy agricultural DC supplies where winding resistance is under 0.5 Ω, inrush surge currents can easily exceed 100 Amperes! "
        "If this initial surge exceeds the diode manufacturer's absolute maximum non-repetitive surge rating (<i>I_FSM</i>, typically 30A for 1N4007), "
        "the diode junction suffers instantaneous thermal vaporization. "
        "To mitigate this risk in tropical irrigation controllers, engineers place an <b>NTC (Negative Temperature Coefficient) power thermistor</b> "
        "in series with the AC mains input. At room temperature (cold start), the NTC presents a high resistance (10 Ω to 50 Ω), quenching the inrush spike "
        "to a benign level. As current flows, internal I²R self-heating causes the NTC resistance to drop to milliohms, restoring near-100% circuit efficiency.",
        styles['DocBody']
    ))

    story.append(create_figure("img_oscilloscope_trace.jpg", "Laboratory Oscilloscope Trace Showing Inrush Transient Current and Output Voltage Smoothing", target_width=5.5*inch))

